const _ = require('lodash');

// Generic Node RedactionStrategy
class GenericNodeRedaction {
    redact(record, redactConfig, maxDepth) {
        if (record.nodeIn) {
            record.nodeIn = redactValues(record.nodeIn, redactConfig.valuePattern, redactConfig.keyPattern, redactConfig.nonRedactableKeys, maxDepth);
        }
        if (record.nodeOut) {
            record.nodeOut = redactValues(record.nodeOut, redactConfig.valuePattern, redactConfig.keyPattern, redactConfig.nonRedactableKeys, maxDepth);
        }
        return record;
    }
}

// HTTP Request RedactionStrategy
class HttpRequestRedaction extends GenericNodeRedaction {
    redact(record, redactConfig, maxDepth) {
        super.redact(record, redactConfig, maxDepth);
        const apiExecution = {
            request: _.toPlainObject(record.nodeOut.optsForRunTimeLogs),
            statusCode: record.nodeOut.statusCode,
            response: _.toPlainObject(record.nodeOut.payload),
        };
        record.apiExecution = redactValues(apiExecution, redactConfig.valuePattern, redactConfig.keyPattern, redactConfig.nonRedactableKeys, maxDepth);
        return record;
    }
}

function redactValues(input, valuePattern, keyPattern, nonRedactableKeys, maxDepth, currentDepth = 0) {
    if (currentDepth > maxDepth){
        return obj;
      } 
    if (Array.isArray(input)) {
        return input.map(item => redactValues(item, valuePattern, keyPattern, nonRedactableKeys, currentDepth + 1));
    }
    if (typeof input === "object" && input !== null) {
        const result = {};
        Object.keys(input).forEach((key) => {
            let f = 0;
            keyPattern.forEach((pattern) => {
                if (pattern.test(key)) {
                    f += 1;
                }
            });
            if (f !== 0) {
                input[key] = "[REDACTED]";
            } else {
                if (!nonRedactableKeys.includes(key)) {
                    input[key] = redactValues(input[key], valuePattern, keyPattern, nonRedactableKeys, currentDepth + 1);
                }
            }
        });
        return input;
    }
    if (typeof input === 'string') {
        let rValue;
        let flag = 0;
        valuePattern.forEach((pattern) => {
            if (pattern.test(input)) {
                flag += 1;
            }
        });
        if (flag !== 0) {
            rValue = "[REDACTED]";
        } else {
            rValue = input;
        }
        return rValue;
    }
    return input;
}

module.exports = { HttpRequestRedaction, GenericNodeRedaction, redactValues };